import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";import"./chunks/assets.C6yW3bU8.js";var i=JSON.parse(`{"title":"AWS Elastic Beanstalk 로그 알아보기","description":"","frontmatter":{"title":"AWS Elastic Beanstalk 로그 알아보기","date":"2024-03-01T23:00+0900","tags":["Beanstalk","TailLogs","Bundlelogs"]},"headers":[],"relativePath":"posts/beanstalk-logs.md","filePath":"posts/beanstalk-logs.md","lastUpdated":1787354858000}`),a={name:`posts/beanstalk-logs.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<p><img src="/images/posts/beanstalk-logs/01.png" alt="" loading="lazy"></p><p>AWS Elastic Beanstalk 환경 콘솔의 로그 메뉴에서 로그 요청을 통해 전체(번들) 또는 마지막 100줄(테일) 로그를 조회할 수 있다. 이러한 요청에 대한 로그는 아래의 파일들을 사용하여 가져오며 사용자 권한을 통해 S3 버킷에 저장한 후 다운로드할 수 있게 제공한다. 따라서, 인스턴스 프로파일에 S3에 대한 권한 정책이 포함되어있어야 한다.</p><ul><li>테일 로그 - /opt/elasticbeanstalk/tasks/taillogs.d/</li><li>번들 로그 - /opt/elasticbeanstalk/tasks/bundlelogs.d/</li><li>회전된 로그 - /opt/elasticbeanstalk/tasks/publishlogs.d/</li></ul><blockquote><p>S3에 저장되는 로그 위치는 elasticbeanstalk-{region}-{account-id}/resources/environments/logs 입니다. Elastic Beanstalk는 요청한 번들 또는 테일 로그에 대해서 15분이 경과된 이후에 파일을 S3에서 삭제합니다.</p></blockquote><h4 id="테일-로그" tabindex="-1">테일 로그 <a class="header-anchor" href="#테일-로그" aria-label="Permalink to “테일 로그”">​</a></h4><p>테일(마지막 100줄) 로그는 EB 엔진 및 Nginx 그리고 애플리케이션 서버 로그의 마지막 100줄을 모아 단일 텍스트 파일을 생성하고 S3에 업로드한다. Amazon Linux 2 리눅스 플랫폼에서 포함되는 로그 항목은 아래와 같다.</p><ul><li>/var/log/web.stdout.log</li><li>/var/log/eb-engine.log</li><li>/var/log/eb-hooks.log</li><li>/var/log/nginx/access.log</li><li>/var/log/nginx/error.log</li></ul><h4 id="번들-로그" tabindex="-1">번들 로그 <a class="header-anchor" href="#번들-로그" aria-label="Permalink to “번들 로그”">​</a></h4><p>번들(전체) 로그는 시스템 전체 메시지 뿐만 아니라 yum 및 cron 로그와 같은 다양한 로그를 포함하여 Zip 파일로 압축한 후 S3에 업로드한다. 다운로드한 번들 로그에는 아래와 같은 로그 항목이 포함되어있다.</p><ul><li>/var/log/healthd/</li><li>/var/log/nginx/</li><li>/var/log/rotate/</li><li>/var/log/cfn-hup.log</li><li>/var/log/cfn-init.log</li><li>/var/log/cfn-init-cmd.log</li><li>/var/log/cfn-wire.log</li><li>/var/log/cloud-init.log</li><li>/var/log/cloud-init-output.log</li><li>/var/log/cron</li><li>/var/log/eb-cfn-init.log</li><li>/var/log/eb-cfn-init-call.log</li><li>/var/log/eb-engine.log</li><li>/var/log/eb-publish.log</li><li>/var/log/eb-tools.log</li><li>/var/log/messages</li><li>/var/log/web.stdout.log</li><li>/var/log/yum.log</li></ul><blockquote><p>번들 로그에는 시스템 전반적인 메시지를 포함하는 /var/log/messages 가 포함되어있어 더 자세하게 원인을 분석할 수 있습니다.</p></blockquote><h4 id="로그-로테이션" tabindex="-1">로그 로테이션 <a class="header-anchor" href="#로그-로테이션" aria-label="Permalink to “로그 로테이션”">​</a></h4><p>AWS Elastic Beanstalk 의 리눅스 플랫폼에서는 logrotate 를 사용해서 로그를 주기적으로 회전하고 Amazon S3에 업로드한다. 환경 콘솔에서 요청하는 번들 또는 마지막 100줄 로그 요청에는 회전되는 로그는 포함되지 않는다. 로그 회전에 대한 구성 파일은 /etc/logrotate.elasticbeanstalk.hourly/ 에서 찾을 수 있으며 /etc/cron.hourly/ 에서 크론 작업으로 호출된다.</p><hr><p>서버 엔지니어 또는 데브옵스 엔지니어에게 전달받은 로그들이 어떠한 정보를 포함하고 있는지를 알고 빠르고 자세하게 문제에 대한 원인을 분석하는데에 사용하는 것에 대한 역량은 백엔드 엔지니어에게 필요한 부분이다.</p>`,15)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};